import "dotenv/config"
import fs from "node:fs"
import os from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"

// Compares the two schema sources this repository maintains:
//
//   local  — SQLite, generated by Payload's push mode straight from the Payload config
//   prod   — Postgres, built by the hand-written migrations in migrations/
//
// Nothing reconciles them automatically, so a column added to a migration but not to the
// config (or the reverse) goes unnoticed until a query fails in one environment only.
// This check needs no database credential: it builds a throwaway SQLite file from the
// config and reads the migrations as text.
//
// Usage:  pnpm check:schema-parity
// Exit:   0 when the two agree, 1 when they differ.

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")

// ---------------------------------------------------------------- local (config → SQLite)

const tmpDb = path.join(fs.mkdtempSync(path.join(os.tmpdir(), "parity-")), "parity.db")
process.env.DATABASE_URL = `file:${tmpDb}`
process.env.PAYLOAD_DB_PUSH = "true"

const { getPayload } = await import("payload")
const { default: config } = await import("@payload-config")

console.log("[parity] Building a throwaway SQLite schema from the Payload config…")
await getPayload({ config })

const { createClient } = await import("@libsql/client")
const client = createClient({ url: `file:${tmpDb}` })

const tableRows = await client.execute(
  "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",
)

/** @type {Map<string, Set<string>>} */
const local = new Map()
for (const row of tableRows.rows) {
  const table = String(row.name)
  const cols = await client.execute(`SELECT name FROM pragma_table_info('${table}')`)
  local.set(table, new Set(cols.rows.map((c) => String(c.name))))
}
client.close()
fs.rmSync(path.dirname(tmpDb), { recursive: true, force: true })

// ------------------------------------------------------------- prod (migrations → Postgres)

/** @type {Map<string, Set<string>>} */
const prod = new Map()
const addColumn = (table, column) => {
  if (!prod.has(table)) prod.set(table, new Set())
  if (column) prod.get(table).add(column)
}

const migrationFiles = fs
  .readdirSync(path.join(root, "migrations"))
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .sort()

for (const file of migrationFiles) {
  const sql = fs.readFileSync(path.join(root, "migrations", file), "utf8")

  // Only the up() half describes the schema production actually has.
  const upBody = sql.split(/export async function down/)[0]

  for (const m of upBody.matchAll(/CREATE TABLE(?:\s+IF NOT EXISTS)?\s+"([^"]+)"\s*\(([\s\S]*?)\n\s*\);/gi)) {
    const table = m[1]
    addColumn(table, null)
    for (const line of m[2].split("\n")) {
      const col = line.match(/^\s*"([a-z0-9_]+)"\s+/i)
      if (col) addColumn(table, col[1])
    }
  }
  for (const m of upBody.matchAll(
    /ALTER TABLE\s+"([^"]+)"\s+ADD COLUMN(?:\s+IF NOT EXISTS)?\s+"([^"]+)"/gi,
  )) {
    addColumn(m[1], m[2])
  }
  for (const m of upBody.matchAll(/ALTER TABLE\s+"([^"]+)"\s+DROP COLUMN(?:\s+IF EXISTS)?\s+"([^"]+)"/gi)) {
    prod.get(m[1])?.delete(m[2])
  }
  for (const m of upBody.matchAll(/ALTER TABLE\s+"([^"]+)"\s+RENAME TO\s+"([^"]+)"/gi)) {
    const from = m[1]
    const to = m[2]
    if (prod.has(from)) {
      prod.set(to, prod.get(from))
      prod.delete(from)
    }
  }
  for (const m of upBody.matchAll(/DROP TABLE(?:\s+IF EXISTS)?\s+"([^"]+)"/gi)) {
    prod.delete(m[1])
  }
}

// ------------------------------------------------------------------------------- compare

// The two directions are not equally serious, so they are reported separately.
//
//   missing  — the config declares it, no migration creates it. Production will fail a
//              query the local database serves. This fails the check.
//   orphaned — a migration creates it, the config no longer declares it. Dead weight in
//              Postgres that nothing reads. Reported, but does not fail the check, so a
//              real breakage is never buried under pre-existing cleanup debt.

const missing = []
const orphaned = []

for (const [table, cols] of local) {
  if (!prod.has(table)) {
    missing.push(`table "${table}" — the config declares it, no migration creates it`)
    continue
  }
  for (const col of cols) {
    if (!prod.get(table).has(col)) {
      missing.push(`"${table}"."${col}" — the config declares it, no migration adds it`)
    }
  }
}

for (const [table, cols] of prod) {
  if (!local.has(table)) {
    orphaned.push(`table "${table}" — a migration creates it, the config no longer declares it`)
    continue
  }
  for (const col of cols) {
    if (!local.get(table).has(col)) {
      orphaned.push(`"${table}"."${col}" — a migration adds it, the config no longer declares it`)
    }
  }
}

console.log(
  `[parity] config-built schema: ${local.size} tables · migrations: ${prod.size} tables · ${migrationFiles.length} migrations read`,
)

if (orphaned.length > 0) {
  console.log(`\n[parity] ${orphaned.length} orphaned in Postgres (not fatal — nothing reads them):\n`)
  for (const o of orphaned.sort()) console.log(`  · ${o}`)
  console.log(
    "\n[parity] These are safe to leave. Removing them needs a migration and is a data decision.",
  )
}

if (missing.length === 0) {
  console.log("\n[parity] OK — every table and column the config declares has a migration.")
  process.exit(0)
}

console.log(`\n[parity] ${missing.length} MISSING FROM PRODUCTION — this will 500 on Vercel:\n`)
for (const m of missing.sort()) console.log(`  · ${m}`)
console.log(
  "\n[parity] Add a migration in migrations/ and register it in migrations/index.ts.\n" +
    "         Authoring command: pnpm migrate:create:vercel",
)
process.exit(1)
